using ghidra.sleigh.grammar;

// Equation preceded by ellipses
public class EquationLeftEllipsis : PatternEquation {

	private PatternEquation eq;

	/* @Override */
	public void dispose() {
		PatternEquation.release(eq);
	}

	public EquationLeftEllipsis(Location location, PatternEquation e) : base(location)
    {
		(eq = e).layClaim();
	}

	/* @Override */
	public void genPattern(VectorSTL<TokenPattern> ops) {
		eq.genPattern(ops);
		setTokenPattern(eq.getTokenPattern());
		getTokenPattern().setLeftEllipsis(true);
	}

	/* @Override */
	public void operandOrder(Constructor ct, VectorSTL<OperandSymbol> order) {
		eq.operandOrder(ct, order); // List operands
	}

	/* @Override */
	public bool resolveOperandLeft(OperandResolve state) {
		int cur_base = state.@base;
		state.@base = -2;
		bool res = eq.resolveOperandLeft(state);
		if (!res) return false;
		state.@base = cur_base;
		return true;
	}
}
